PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE Buildings (
    Location TEXT PRIMARY KEY,
    Building TEXT
, Google_Maps_Link TEXT, Exterior_Image_URL TEXT);
CREATE TABLE Rooms (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    Location TEXT,
    Room_Num TEXT,
    Floor TEXT,
    Description TEXT,
    Access_Key TEXT,
    Notes TEXT, Y_Coordinate REAL, Room_Panorama_URL TEXT, X_Coordinate REAL, floorplanid INTEGER,
    FOREIGN KEY (Location) REFERENCES Buildings(Location)
);
CREATE TABLE FloorPlans (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    Location TEXT,
    Floor TEXT,
    Image_URL TEXT,
    FOREIGN KEY (Location) REFERENCES Buildings(Location),
    UNIQUE(Location, Floor)
);
CREATE TABLE Equipment (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    accountingName TEXT,
    Description TEXT,
    Location TEXT,
    Room_Raw TEXT,
    Room_id INTEGER,
    Notes TEXT,
    Serial_Num TEXT,
    Manufacturer TEXT,
    Vendor TEXT,
    Images TEXT DEFAULT '[]', Status, createdAt INTEGER, updatedAt INTEGER, reviewedAt INTEGER, reviewedBy TEXT, scadaName TEXT, previousAccountingName TEXT, NewEquipment Integer Not Null Default 0,
    FOREIGN KEY (Room_id) REFERENCES Rooms(id)
);
CREATE TABLE EquipmentChangeLog (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        equipmentId TEXT NOT NULL,
        field TEXT NOT NULL,
        oldValue TEXT,
        newValue TEXT,
        changedAt TEXT NOT NULL,
        changedBy TEXT,
        source TEXT,
        correlationId TEXT
      );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_equipment_reviewed_updated ON Equipment(reviewedAt, updatedAt);
CREATE INDEX idx_equipment_location_updated ON Equipment(Location, updatedAt);
CREATE INDEX idx_equipment_location_created ON Equipment(Location, createdAt);
CREATE INDEX idx_ecl_changedAt ON EquipmentChangeLog(changedAt);
CREATE INDEX idx_ecl_equipmentId_changedAt ON EquipmentChangeLog(equipmentId, changedAt);
CREATE INDEX idx_ecl_field_changedAt ON EquipmentChangeLog(field, changedAt);
